//! Kenya source clinical resource rows and publisher-emitted downloads.
use super::{common,static_list::blocks_for,Adapter,PlanRow};
use crate::guidelines::doc::{GuidelineDoc,Rights};
use crate::guidelines::fetch::{Fetched,Fetcher};
use crate::guidelines::html::{sel,text_of};
use crate::guidelines::registry::SourceEntry;
use anyhow::{bail,Context,Result};
use scraper::Html;
use serde_json::json;
use std::collections::HashSet;
use url::Url;
pub struct KenyaMental;
const ROOT:&str="https://mental.health.go.ke/resources/";
async fn public_html(f:&Fetcher,url:&str)->Result<Fetched>{let p=f.get(url).await?;if p.record.status!=200||!p.is_html(){bail!("Kenya source returned HTTP {} or non-HTML",p.record.status)};if Url::parse(&p.record.final_url)?.host_str()!=Some("mental.health.go.ke"){bail!("Kenya source redirected off origin")};Ok(p)}
fn gate(root:&scraper::ElementRef)->Result<()> {if root.select(&sel("form input[type='password'], form input[name='password'], form [name='wpdm_password'], form iframe[src*='recaptcha'], form input[name*='captcha']")).next().is_some(){bail!("Kenya public content root contains credential or CAPTCHA gate")};Ok(())}
/// Clinical practice documents of the resource table: guidelines, protocols, guides/guidance (e.g. the COVID-19
/// MHPSS guide, psychological first aid guide) and standard operating procedures for MHPSS providers. Policies,
/// action plans, reports, surveys, audio and memoranda are not clinical guidance.
fn clinical_title(low:&str)->bool{["guideline","protocol","guide","guidance","standard operating procedure"].iter().any(|k|low.contains(k))}
fn catalog(raw:&str,base:&Url)->Result<Vec<(String,String)>>{let d=Html::parse_document(raw);let root=d.select(&sel("main#main article")).next().context("Kenya resource article missing")?;gate(&root)?;let mut seen=HashSet::new();let mut out=vec![];for a in root.select(&sel("tr.__dt_row a.package-title[href]")){let title=text_of(&a);let low=title.to_lowercase();if !clinical_title(&low){continue}let Some(url)=a.value().attr("href").and_then(|h|common::link(base,h)) else{continue};let u=Url::parse(&url)?;if u.host_str()==Some("mental.health.go.ke")&&u.path().starts_with("/download/")&&seen.insert(url.clone()){out.push((url,title));}}if out.is_empty(){bail!("Kenya source clinical rows missing")};Ok(out)}
fn landing(raw:&str,base:&Url)->Result<(String,String)>{let d=Html::parse_document(raw);let root=d.select(&sel("main#main article")).next().context("Kenya download article missing")?;gate(&root)?;let title=root.select(&sel("h1.entry-title")).next().map(|e|text_of(&e)).context("Kenya download title missing")?;let urls=root.select(&sel("a.wpdm-download-link[data-downloadurl]")).filter_map(|a|a.value().attr("data-downloadurl").and_then(|h|common::link(base,h))).collect::<Vec<_>>();if urls.len()!=1{bail!("Kenya expected one source-emitted download, found {}",urls.len())};let u=Url::parse(&urls[0])?;if u.host_str()!=Some("mental.health.go.ke")||u.path()!=base.path(){bail!("Kenya download did not target its source record")};Ok((title,urls[0].clone()))}
fn rights(blocks:&[crate::guidelines::doc::Block],url:&str)->Rights {let notice=blocks.iter().take(150).map(|b|b.text.as_str()).find(|s|{let t=s.to_lowercase();(t.contains("without the prior written permission") && t.contains("publication"))||(t.contains("source is acknowledged")&&t.contains("commercial purposes"))});match notice {Some(n)=>Rights{status:"restricted".into(),restrictions:vec![n.into()],evidence_urls:vec![url.into()],note:Some("This notice applies to this PDF; third-party material rights are separate.".into()),..Default::default()},None=>Rights{status:"unknown".into(),..Default::default()}}}
#[async_trait::async_trait]
impl Adapter for KenyaMental{
 async fn discover(&self,src:&SourceEntry,f:&Fetcher,limit:Option<usize>)->Result<Vec<PlanRow>>{if limit==Some(0){return Ok(vec![])}let c=public_html(f,src.catalog_url.as_deref().unwrap_or(ROOT)).await?;let entries=catalog(&c.text(),&Url::parse(&c.record.final_url)?)?;let mut rows=vec![];
  for (url,title) in entries {let mut r=PlanRow{source_id:src.id.clone(),doc_key:format!("kenya-{}-unresolved",common::short_hash(&url)),url:url.clone(),title:Some(title),rendition:Some("pdf".into()),version:None,extra:json!({"landing_url":url,"catalog_fetch":c.record})};
   match public_html(f,&url).await{Ok(p)=>match landing(&p.text(),&Url::parse(&p.record.final_url)?){Ok((title,pdf))=>{r.title=Some(title);r.url=pdf;r.extra["landing_fetch"]=json!(p.record);match f.get_ok(&r.url).await{Ok(q) if q.is_pdf() && Url::parse(&q.record.final_url).is_ok_and(|u|u.host_str()==Some("mental.health.go.ke"))=>{r.doc_key=format!("kenya-{}-{}",common::short_hash(&url),&q.record.sha256[..12]);r.extra["pdf_sha256"]=json!(q.record.sha256);},Ok(_)=>r.extra["discovery_error"]=json!("Kenya source download was not a PDF"),Err(e)=>r.extra["discovery_error"]=json!(format!("{e:#}"))}},Err(e)=>r.extra["discovery_error"]=json!(format!("{e:#}"))},Err(e)=>r.extra["discovery_error"]=json!(format!("{e:#}"))};rows.push(r);if limit.is_some_and(|n|rows.len()>=n){break}}
  Ok(rows)
 }
 async fn extract(&self,src:&SourceEntry,f:&Fetcher,row:&PlanRow)->Result<GuidelineDoc>{if let Some(e)=row.extra["discovery_error"].as_str(){bail!("Kenya discovery: {e}")};let p=f.get_ok(&row.url).await?;if !p.is_pdf()||Url::parse(&p.record.final_url)?.host_str()!=Some("mental.health.go.ke")||row.extra["pdf_sha256"].as_str()!=Some(p.record.sha256.as_str()){bail!("Kenya PDF changed or unavailable; re-plan")};let (blocks,mut warnings,_)=blocks_for(&p,None,30).await?;if blocks.is_empty(){bail!("Kenya PDF yielded no text")};let rights=rights(&blocks,&row.url);warnings.push("PDF tables, care pathways, nested medication criteria, visual algorithms and page fidelity require original-page review; recommendation grades are not inferred.".into());warnings.push("Strict publisher article and download selectors were used because the generic login heuristic sees unrelated template strings. Genuine password, CAPTCHA, HTTP 403 or changed templates remain errors. Clinical title filters do not establish complete site inventory.".into());let title=row.title.clone().unwrap_or_default();let low=title.to_lowercase();let role=if low.contains("protocol"){"protocol"}else if low.contains("guideline"){"guideline"}else if low.contains("standard operating procedure"){"standard_operating_procedure"}else if low.contains("guidance"){"guidance"}else{"guide"};let mut fetches=vec![];for key in ["catalog_fetch","landing_fetch"]{if let Ok(r)=serde_json::from_value::<crate::guidelines::doc::FetchRecord>(row.extra[key].clone()){fetches.push(r)}}fetches.push(p.record);Ok(GuidelineDoc{source_id:src.id.clone(),doc_key:row.doc_key.clone(),work_key:row.extra["landing_url"].as_str().map(|u|format!("kenya-{}",common::short_hash(u))),title,url:row.url.clone(),item_type:Some(role.into()),status:"unknown".into(),rights,blocks,fetches,warnings,search_metadata:json!({"landing_url":row.extra["landing_url"]}),..Default::default()})}
}
#[cfg(all(test, feature = "guideline-fixtures"))] mod tests{
 use super::*;
 const CAT:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ke_moh_mental/catalog.html"));
 const COMMON:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ke_moh_mental/common.html"));
 const SUBSTANCE:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ke_moh_mental/substance.html"));
 const G:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ke_moh_mental/guideline-rights.json"));
 const P:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ke_moh_mental/protocol-rights.json"));
 #[test] fn genuine_downloads_rights_and_gate(){let c=catalog(CAT,&Url::parse(ROOT).unwrap()).unwrap();assert!(c.iter().any(|(_,t)|t.contains("Common Mental Disorders")));assert!(c.iter().any(|(_,t)|t.contains("Substance Use Disorders")));let u=Url::parse("https://mental.health.go.ke/download/national-clinical-guidelines-for-management-of-common-mental-disorders/").unwrap();let (_,pdf)=landing(COMMON,&u).unwrap();assert!(pdf.contains("wpdmdl=471")&&pdf.contains("refresh="));let (_,p)=landing(SUBSTANCE,&Url::parse("https://mental.health.go.ke/download/the-national-protocol-for-treatment-of-substance-use-disorders-in-kenya-2017/").unwrap()).unwrap();assert!(p.contains("wpdmdl=349"));let blocks:Vec<crate::guidelines::doc::Block>=serde_json::from_str(G).unwrap();assert!(rights(&blocks,&pdf).restrictions[0].contains("commercial purposes"));let blocks:Vec<crate::guidelines::doc::Block>=serde_json::from_str(P).unwrap();assert!(rights(&blocks,&p).restrictions[0].contains("prior written permission"));let gated=COMMON.replace("<h1 class=\"entry-title\"","<form><input type='password'></form><h1 class=\"entry-title\"");assert!(landing(&gated,&u).is_err());}
 #[tokio::test] async fn offline_real_landing_keeps_download_failure_visible(){let tmp=tempfile::tempdir().unwrap();let f=Fetcher::new(tmp.path(),true,500,1<<20,"").unwrap();f.seed_cache_for_tests(ROOT,CAT.as_bytes(),"text/html");let page="https://mental.health.go.ke/download/national-clinical-guidelines-for-management-of-common-mental-disorders/";f.seed_cache_for_tests(page,COMMON.as_bytes(),"text/html");let src:SourceEntry=serde_json::from_value(json!({"id":"ke_moh_mental","access":"public","enabled":true,"catalog_url":ROOT})).unwrap();let rows=KenyaMental.discover(&src,&f,None).await.unwrap();let r=rows.iter().find(|r|r.extra["landing_url"]==page).unwrap();assert!(r.url.contains("wpdmdl=471"));assert!(r.extra["discovery_error"].is_string());assert!(KenyaMental.extract(&src,&f,r).await.is_err());}

 #[tokio::test]async fn actual_protocol_clinical_and_guideline_cover_are_distinct(){
  let protocol=include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ke_moh_mental/protocol-clinical-page-30.pdf"));let guideline=include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ke_moh_mental/guideline-cover-page-2.pdf"));let g="https://mental.health.go.ke/download/national-clinical-guidelines-for-management-of-common-mental-disorders/";let p="https://mental.health.go.ke/download/the-national-protocol-for-treatment-of-substance-use-disorders-in-kenya-2017/";let (_,gu)=landing(COMMON,&Url::parse(g).unwrap()).unwrap();let (_,pu)=landing(SUBSTANCE,&Url::parse(p).unwrap()).unwrap();let tmp=tempfile::tempdir().unwrap();let f=Fetcher::new(tmp.path(),true,500,1<<20,"").unwrap();f.seed_cache_for_tests(ROOT,CAT.as_bytes(),"text/html");f.seed_cache_for_tests(g,COMMON.as_bytes(),"text/html");f.seed_cache_for_tests(p,SUBSTANCE.as_bytes(),"text/html");f.seed_cache_for_tests(&gu,guideline,"application/pdf");f.seed_cache_for_tests(&pu,protocol,"application/pdf");let src:SourceEntry=serde_json::from_value(json!({"id":"ke_moh_mental","access":"public","enabled":true,"catalog_url":ROOT})).unwrap();let rows=KenyaMental.discover(&src,&f,None).await.unwrap();let pr=rows.iter().find(|r|r.url==pu).unwrap();let gr=rows.iter().find(|r|r.url==gu).unwrap();let pd=KenyaMental.extract(&src,&f,pr).await.unwrap();let clinical=pd.blocks.iter().map(|b|b.text.as_str()).collect::<Vec<_>>().join(" ").to_lowercase();assert!(clinical.contains("frames")&&clinical.contains("referral")&&clinical.contains("assessment"));assert_eq!(pd.item_type.as_deref(),Some("protocol"));assert!(pd.warnings.iter().any(|w|w.contains("medication criteria")));let gd=KenyaMental.extract(&src,&f,gr).await.unwrap();assert_eq!(gd.item_type.as_deref(),Some("guideline"));assert_eq!(gd.rights.status,"unknown");assert!(!gd.blocks.is_empty());assert_ne!(gd.doc_key,pd.doc_key);
 }

 #[tokio::test]async fn genuine_rights_pages_remain_document_specific(){let g="https://mental.health.go.ke/download/national-clinical-guidelines-for-management-of-common-mental-disorders/";let p="https://mental.health.go.ke/download/the-national-protocol-for-treatment-of-substance-use-disorders-in-kenya-2017/";let gp=include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ke_moh_mental/rights-33983bf9-page-4.pdf"));let pp=include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ke_moh_mental/rights-f9e7fc13-page-4.pdf"));let(_,gu)=landing(COMMON,&Url::parse(g).unwrap()).unwrap();let(_,pu)=landing(SUBSTANCE,&Url::parse(p).unwrap()).unwrap();let tmp=tempfile::tempdir().unwrap();let f=Fetcher::new(tmp.path(),true,500,1<<20,"").unwrap();f.seed_cache_for_tests(ROOT,CAT.as_bytes(),"text/html");f.seed_cache_for_tests(g,COMMON.as_bytes(),"text/html");f.seed_cache_for_tests(p,SUBSTANCE.as_bytes(),"text/html");f.seed_cache_for_tests(&gu,gp,"application/pdf");f.seed_cache_for_tests(&pu,pp,"application/pdf");let src:SourceEntry=serde_json::from_value(json!({"id":"ke_moh_mental","access":"public","enabled":true,"catalog_url":ROOT})).unwrap();let rows=KenyaMental.discover(&src,&f,None).await.unwrap();let gr=rows.iter().find(|r|r.url==gu).unwrap();let pr=rows.iter().find(|r|r.url==pu).unwrap();let gd=KenyaMental.extract(&src,&f,gr).await.unwrap();let pd=KenyaMental.extract(&src,&f,pr).await.unwrap();assert_eq!(gd.rights.status,"restricted","guideline blocks: {:#?}",gd.blocks);assert!(gd.rights.restrictions.iter().any(|s|s.contains("source is acknowledged")&&s.contains("commercial purposes")));assert_eq!(pd.rights.status,"restricted","protocol blocks: {:#?}",pd.blocks);assert!(pd.rights.restrictions.iter().any(|s|s.contains("prior written permission")));assert!(gd.rights.evidence_urls.contains(&gu)&&pd.rights.evidence_urls.contains(&pu));assert!(!gd.rights.restrictions.iter().any(|s|s.contains("prior written permission")));}

}

#[cfg(all(test, feature = "guideline-fixtures"))] mod clinical_rows{
 use super::*;
 const CAT:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ke_moh_mental/catalog.html"));
 #[test] fn guides_and_sops_join_guidelines_and_protocols_but_not_policy_or_reports(){
  let c=catalog(CAT,&Url::parse(ROOT).unwrap()).unwrap();let titles:Vec<String>=c.iter().map(|(_,t)|t.to_lowercase()).collect();
  assert!(titles.iter().any(|t|t.contains("common mental disorders"))&&titles.iter().any(|t|t.contains("substance use disorders")));
  assert!(titles.iter().any(|t|t.contains("psychological first aid")));assert!(titles.iter().any(|t|t.contains("standard operating procedures")));
  assert!(!titles.iter().any(|t|t.contains("policy")||t.contains("action plan")||t.contains("survey")||t.contains("audio")||t.contains("memoranda")||t.contains("investment case")));
  assert_eq!(c.len(),7,"{titles:?}");
 }
}
